[Form]
public class NDXRicoBVAdministration extends FormRun implements NDXFormHandlerIncludedI
{
    NDXRicoBVAdministrationForm formhandler;
    QueryBuildRange qbrNDX_KBV2RicoKalkMap;
    QueryBuildRange qbrNDX_KBV2RicoProtTable;
}

/// <summary>
/// PaffH 24.01.24
/// </summary>
public void init()
{
    super();
    formhandler = NDXRicoBVAdministrationForm::NewFromForm(element);
    FormTabPageDetailsPanel.setFocus();
    FormGridNDX_KBV2RicoProtLine.visibleRows(12);
    FormGridNDX_KBV2RicoKalkMap.visibleRows(20);
    FormGridNDX_KBV2RicoKalkQuotationNew.visibleRows(20);
    NDX_KBV2RicoKalkMap_ds.object(Fieldnum(NDX_KBV2RicoKalkMap, RicoKalkBVNr)).allowEdit(xUserInfo::isSysAdmin());
}

/// <summary>
/// PaffH 25.01.24
/// </summary>
public void run()
{
    super();
}

public NDXFormHandler parmFormhandler()
{
    return formhandler;
}

/// <summary>
/// PaffH 30.01.24
/// show batchJob details (BatchJobEnhanced)
/// </summary>
/// <param name = "_batchHeaderRecId">RefRecId</param>
public void showBatchJob(RefRecId _batchHeaderRecId)
{
    Args args;
    BatchJob batchJob;
    select firstonly batchJob where batchJob.RecId == _batchHeaderRecId;
    args = new Args();
    args.name(formStr(BatchJobEnhanced));
    args.record(batchJob);
    MenuFunction menuFunction = new MenuFunction(menuItemDisplayStr(BatchJobEnhanced), MenuItemType::Display);
    menuFunction.run(args);
}

/// <summary>
/// PaffH 24.01.24
/// </summary>
public void init()
{
    super();
    this.query().dataSourceName(this.name()).addSortField(fieldNum(NDX_KBV2RicoProtTable,KBVProtIDInt), SortOrder::Descending);
    qbrNDX_KBV2RicoProtTable = this.query().dataSourceName(this.name()).addRange(fieldNum(NDX_KBV2RicoProtTable, RicoKalkBVNr));
}

/// <summary>
/// PaffH 25.01.24
/// </summary>
public void init()
{
    super();
    this.query().dataSourceName(this.name()).addOrderByField(fieldnum(NDX_KBV2RicoKalkMap, RicoKalkBVNr), SortOrder::Descending);
    qbrNDX_KBV2RicoKalkMap = this.query().dataSourceName(this.name()).addRange(fieldNum(NDX_KBV2RicoKalkMap, RicoKalkBVNr));
}

/// <summary>
/// PaffH 25.01.24
/// </summary>
public void linkActive()
{
    super();

    if (element.args() &&
        element.args().dataset() == tableNum(NDX_KBV2RicoKalkMap))
    {
        NDX_KBV2RicoKalkMap NDX_KBV2RicoKalkMapTmp = element.args().record();
        qbrNDX_KBV2RicoProtTable.value(queryValue(NDX_KBV2RicoKalkMapTmp.RicoKalkBVNr));
        NDX_KBV2RicoProtTable_ds.executeQuery();
        FormTabPageMappings.visible(false);
        FormTabPageNDX_KBV2RicoKalkMap.visible(false);
    }
}

