/// <summary>
/// PaffH 31.01.24
/// </summary>
public void init()
{
    super();
    QueryBuildDataSource qbds = this.query().dataSourceName(this.name());
    qbds.addRange(fieldNum(Batch, ClassNumber)).value(queryValue(classNum(NDXRicoKalkGetQuotationController3Month)));

    // don't show assigned batch job
    RecId batchHeaderRefRecId = KCS_KBVParameters::find().NDXBatchHeaderRefRecIdRicoKalkGetQuotations3Month;
    if (batchHeaderRefRecId)
    {
        qbds.addRange(fieldNum(Batch, BatchJobId)).value(SysQuery::valueNot(batchHeaderRefRecId));
    }
}

